189:   function enemyTurn() {
190:     if (state.phase !== 'battle' || state.enemyHp <= 0) return;
191:     state.busy = true;
192:     $('turnBadge').classList.add('enemy-turn');
193:     $('turnBadge').innerHTML = '<span class="turn-dot"></span> ENEMY TURN';
194:     setText('intentText', 'The enemy lunges!');
195:     render();
196:     actionTimer = window.setTimeout(() => {
197:       if (state.phase !== 'battle') return;
198:       let damage = Math.max(1, Math.round(state.enemy.attack * (1 + (state.floor - 1) * .075)) - state.armor);
199:       const heavy = Math.random() < .22;
200:       if (heavy) damage = Math.round(damage * 1.55);
201:       if (state.guarding) { damage = Math.max(1, Math.ceil(damage / 2)); state.guarding = false; }
202:       state.hp = Math.max(0, state.hp - damage);
203:       showFloat(`−${damage}`, 'damage', true);
204:       $('enemyWrap').classList.remove('hit');
205:       log(`${state.enemy.name} ${heavy ? 'unleashes a heavy strike' : 'strikes'} for ${damage} damage${state.armor ? ` (${state.armor} absorbed)` : ''}.`);
