210:         state.enemyHp = Math.max(0, state.enemyHp - burnDamage);
211:         state.burn--;
212:         showFloat(`−${burnDamage} burn`);
213:       }
214:       const regenHp = state.hp > 0 ? Math.min(2, state.maxHp - state.hp) : 0;
215:       const regenMp = Math.min(1, state.maxMp - state.mp);
