220:       log(`${state.enemy.name} ${heavy ? 'unleashes a heavy strike' : 'strikes'} for ${damage} damage${state.armor ? ` (${state.armor} absorbed)` : ''}.${burnDamage ? ` Burn deals ${burnDamage}.` : ''} Turn’s end: +${regenHp} HP, +${regenMp} FP.`);
