235:     player.classList.remove('player-hit', 'player-knight-attack', 'player-mage-attack', 'player-archer-attack');
236:     void player.offsetWidth;
237:     player.classList.add(animation);
238:   }
239:   function doAction(action) {
240:     if (state.phase !== 'battle' || state.busy || !state.classId) return;
241:     let damage = 0;
242:     let turnConsumed = false;
243:     const classSkill = classSkills[action];
244:     const book = action.startsWith('skill:') ? skillBooks.find(item => item.id === action.slice(6)) : null;
245:     if (classSkill) {
246:       if (!classes[state.classId].skills.includes(action) || state.mp < classSkill.cost || (classSkill.heal && state.hp >= state.maxHp)) return;
247:       state.mp -= classSkill.cost;
248:       if (classSkill.heal) {
249:         const healed = Math.min(classSkill.heal, state.maxHp - state.hp);
250:         state.hp += healed; showFloat(`+${healed}`, 'heal', true);
251:       }
252:       if (classSkill.guard) state.guarding = true;
253:       if (classSkill.burn) state.burn = classSkill.burn;
254:       if (classSkill.damage) damage = Math.round(state.power * classSkill.damage + classSkill.bonus + Math.random() * 5);
255:       log(`${classSkill.name}: ${classSkill.heal ? 'restores your vitality' : 'strikes for ' + damage + ' damage'}${classSkill.guard ? ' and braces for the next strike' : ''}${classSkill.burn ? ' as the foe catches fire' : ''}.`);
256:       beep(classSkill.classId === 'mage' ? 480 : classSkill.classId === 'archer' ? 390 : 340);
257:       turnConsumed = true;
258:     } else if (book) {
259:       if (!state.learnedSkills.includes(book.id) || state.mp < book.cost || (book.heal && state.hp >= state.maxHp)) return;
260:       state.mp -= book.cost;
261:       if (book.heal) {
262:         const healed = Math.min(book.heal, state.maxHp - state.hp);
263:         state.hp += healed; showFloat(`+${healed}`, 'heal', true);
264:       }
265:       if (book.id === 'aegis') state.guarding = true;
266:       if (book.damage) damage = Math.round(state.power * book.damage + book.bonus + Math.random() * 7);
267:       log(book.heal ? `${book.name} restores your vitality${book.id === 'aegis' ? ' and braces you for the next strike' : ''}.` : `${book.name} strikes for ${damage} damage.`);
268:       beep(610); turnConsumed = true;
269:     } else {
270:       switch (action) {
271:         case 'attack':
272:           damage = state.power + Math.floor(Math.random() * 5);
273:           log(`You strike true, dealing ${damage} damage.`); turnConsumed = true; break;
274:         case 'potion': {
275:           if (!state.potions || state.hp >= state.maxHp) return;
276:           state.potions--;
277:           const healed = Math.min(40, state.maxHp - state.hp); state.hp += healed;
278:           showFloat(`+${healed}`, 'heal', true); log(`You drink a health potion and recover ${healed} vitality.`); beep(520); turnConsumed = true; break;
279:         }
280:         case 'ether': {
281:           if (!state.ethers || state.mp >= state.maxMp) return;
282:           state.ethers--;
283:           const restored = Math.min(20, state.maxMp - state.mp); state.mp += restored;
284:           showFloat(`+${restored} FP`, 'heal', true); log(`The focus tonic restores ${restored} focus.`); beep(440); turnConsumed = true; break;
285:         }
286:         case 'guard':
287:           state.guarding = true; log('You brace behind your guard. The next hit will deal half damage.'); beep(180); turnConsumed = true; break;
288:       }
289:     }
290:     if (!turnConsumed) return;
291:     animatePlayer(action);
292:     if (damage > 0) {
293:       state.enemyHp = Math.max(0, state.enemyHp - damage);
294:       showFloat(`−${damage}`);
295:       const wrap = $('enemyWrap'); wrap.classList.remove('hit'); void wrap.offsetWidth; wrap.classList.add('hit');
296:       beep(260 + Math.min(250, damage * 4));
297:     }
298:     render();
299:     if (state.enemyHp <= 0) { window.setTimeout(victory, 350); return; }
300:     enemyTurn();
301:   }
302:   function victory() {
303:     if (state.phase !== 'battle') return;
304:     state.phase = 'shop'; state.busy = false; state.cleared++;
305:     const gold = (state.floor % 5 === 0 ? 28 : 12) + Math.floor(Math.random() * 8);
306:     const gainedXp = state.floor % 5 === 0 ? 32 : 18;
307:     state.gold += gold; state.xp += gainedXp;
308:     let leveled = false;
309:     while (state.xp >= state.level * 40) {
310:       state.xp -= state.level * 40; state.level++; state.maxHp += 12; state.maxMp += 4; state.power += 2; state.hp = Math.min(state.maxHp, state.hp + 25); state.mp = Math.min(state.maxMp, state.mp + 12); leveled = true;
311:     }
312:     if (state.floor > best) { best = state.floor; localStorage.setItem('emberfall-best', String(best)); setText('runRecord', `BEST: FLOOR ${String(best).padStart(2, '0')}`); }
313:     $('shopModal').classList.remove('hidden');
314:     setText('shopTitle', state.floor % 5 === 0 ? 'The Lantern & Latch' : 'The Lantern & Latch');
315:     setText('shopGold', state.gold);
316:     $('continueBtn').innerHTML = `Continue to floor ${String(state.floor + 1).padStart(2, '0')} <span>→</span>`;
317:     log(`Victory! You earn ${gold} gold and ${gainedXp} XP.${leveled ? ' A new level is yours!' : ''}`);
318:     renderShop(); render();
319:   }
320:   function renderShop() {
321:     renderShopStatus();
322:     setText('shopGold', state.gold);
323:     $('shopItems').innerHTML = shopGoods.map(item => `<div class="shop-item"><span class="shop-item-icon">${item.icon}</span><div class="shop-item-copy"><strong>${item.name}</strong><small>${item.info}</small></div><button class="buy-btn" data-buy="${item.id}" ${state.gold < item.price || (item.id === 'heal' && state.hp >= state.maxHp) ? 'disabled' : ''}>◉ ${item.price}</button></div>`).join('');
324:     $('shopItems').querySelectorAll('[data-buy]').forEach(button => button.addEventListener('click', () => buy(button.dataset.buy)));
325:   }
326:   function buy(id) {
327:     const item = shopGoods.find(goods => goods.id === id);
328:     if (!item || state.gold < item.price) return;
329:     if (id === 'heal' && state.hp >= state.maxHp) return;
330:     state.gold -= item.price;
331:     if (id === 'potion') state.potions++;
332:     if (id === 'ether') state.ethers++;
333:     if (id === 'power') state.power += 2;
