    return `<button class="boon-option${owned ? ' owned' : ''}" data-boon="${item.id}" ${owned || legacy.shards < item.price ? 'disabled' : ''}><span><strong>${item.name}</strong><small>${item.info}</small></span><b>${owned ? 'OWNED' : `✧ ${item.price}`}</b></button>`;
