input.newString:
@media (prefers-reduced-motion: reduce) {
  .player-aura, .player-knight-attack, .player-mage-attack, .player-archer-attack, .player-hit { animation-duration: .01ms; }
}

/* Compact party status stays readable without competing with the arena. */
.party-roster {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin: 0 0 10px;
  padding: 8px;
  border: 1px solid #34394b;
  border-radius: 7px;
  background: linear-gradient(120deg, #171a26, #1d2030);
}
.party-turn-label {
  grid-column: 1 / -1;
  display: flex;
  justify-content: space-between;
  color: #aaaebe;
  font: 8px 'DM Mono', monospace;
  letter-spacing: .12em;
}
.party-turn-label span { color: #e8bc72; letter-spacing: .04em; }
.party-member {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 7px;
  padding: 7px;
  border: 1px solid #303546;
  border-radius: 5px;
  background: #202434;
  transition: border-color .2s, background .2s, opacity .2s;
}
.party-member.acting { border-color: #9a8053; background: linear-gradient(120deg, #342e2b, #252536); }
.party-member.down { opacity: .48; filter: grayscale(.7); }
.party-icon {
  display: grid;
  flex: 0 0 27px;
  width: 27px;
  height: 27px;
  place-items: center;
  border: 1px solid #645643;
  border-radius: 50%;
  background: #302b32;
  color: #e8bc72;
  font-size: 13px;
}
.party-member:nth-child(3) .party-icon { color: #c3a2f1; }
.party-member:nth-child(4) .party-icon { color: #91c79d; }
.party-copy { display: grid; min-width: 0; flex: 1; gap: 3px; }
.party-copy strong { overflow: hidden; color: #eee3d2; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.party-copy small { overflow: hidden; color: #9ba2b8; font: 7px 'DM Mono', monospace; text-overflow: ellipsis; white-space: nowrap; }
.party-copy i { display: block; height: 3px; overflow: hidden; border-radius: 9px; background: #3a3540; }
.party-copy i b { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #a9494c, #e87972); transition: width .25s; }
.party-member em { flex: 0 0 auto; color: #c9c4bd; font: 7px 'DM Mono', monospace; font-style: normal; }
.run-reward { margin: 12px 0; padding: 10px; border: 1px solid #68583d; border-radius: 6px; background: #28251f; color: #e8c989; text-align: center; font: 9px 'DM Mono', monospace; line-height: 1.6; }

@media (max-width: 720px) {
  .party-roster { gap: 5px; padding: 6px; }
  .party-member { gap: 5px; padding: 6px 5px; }
  .party-icon { flex-basis: 23px; width: 23px; height: 23px; font-size: 11px; }
  .party-copy strong { font-size: 8px; }
  .party-copy small { font-size: 6px; }
  .party-member em { font-size: 6px; }
}
@media (max-width: 420px) {
  .party-roster { grid-template-columns: 1fr; gap: 4px; }
  .party-turn-label { margin-bottom: 1px; }
  .party-member { min-height: 39px; }
}
@media (max-width: 350px) {
  .party-member { padding: 5px 4px; }
  .party-copy strong { font-size: 7px; }
}

