const target = await fetch('http://127.0.0.1:9222/json/new?http://127.0.0.1:8765/').then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  }
};
function send(method, params = {}) {
  const requestId = ++id;
  ws.send(JSON.stringify({ id: requestId, method, params }));
  return new Promise((resolve, reject) => pending.set(requestId, { resolve, reject }));
}
async function evaluate(expression, awaitPromise = false) {
  const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise });
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
  return result.result.value;
}
await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:8765/' });
await new Promise(resolve => setTimeout(resolve, 600));
const results = {};
results.initial = await evaluate(`({title: document.title, classOptions: document.querySelectorAll('[data-class-choice]').length, boonUI: !!document.querySelector('#boonList')})`);
await evaluate(`document.querySelector('[data-class-choice="mage"]').click()`);
await evaluate(`document.querySelector('[data-menu="skills"]').click()`);
await evaluate(`document.querySelector('[data-action="frost"]').click()`);
results.partyTurn = await evaluate(`({status: document.querySelector('#logText').textContent, turn: document.querySelector('#partyRoster').textContent})`);
// Complete a floor with party strikes, allowing enemy turns to resolve.
results.victory = await evaluate(`(async () => {
  for (let i=0; i<80 && document.querySelector('#shopModal').classList.contains('hidden'); i++) {
    const attack = document.querySelector('[data-action="attack"]');
    if (attack && !attack.disabled) attack.click();
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  return {shop: !document.querySelector('#shopModal').classList.contains('hidden'), log: document.querySelector('#logText').textContent, roster: document.querySelector('#partyRoster').textContent};
})()`, true);
if (results.victory.shop) {
  const before = results.victory.roster;
  await evaluate(`document.querySelector('#continueBtn').click()`);
  results.continue = await evaluate(`({floor: document.querySelector('#floorTop').textContent, roster: document.querySelector('#partyRoster').textContent})`);
  results.continue.before = before;
}
await send('Browser.close');
console.log(JSON.stringify(results, null, 2));

