const http = require('http');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
function getJson(path) { return new Promise((resolve, reject) => http.get(`http://127.0.0.1:9222${path}`, res => { let s=''; res.on('data', x => s += x); res.on('end', () => resolve(JSON.parse(s))); }).on('error', reject)); }
(async () => {
  const target = (await getJson('/json/list')).find(x => x.type === 'page' && x.url.startsWith('http://127.0.0.1:8765'));
  if (!target) throw new Error('test page not found');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let seq = 0; const pending = new Map();
  ws.onmessage = e => { const m=JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  const send = (method, params={}) => new Promise(resolve => { const id=++seq; pending.set(id, resolve); ws.send(JSON.stringify({id,method,params})); });
  const evalJs = async expression => { const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true}); if(r.result.exceptionDetails) throw new Error(r.result.exceptionDetails.text); return r.result.result.value; };
  const click = async selector => evalJs(`(()=>{const e=document.querySelector(${JSON.stringify(selector)}); if(!e) throw Error('missing '+${JSON.stringify(selector)}); e.click(); return true})()`);
  const wait = async ms => sleep(ms);
  await send('Page.enable'); await send('Runtime.enable');
  await evalJs(`localStorage.setItem('emberfall-legacy', JSON.stringify({shards:20,achievements:[],boons:['phoenix']})); location.reload()`);
  await wait(500);
  await click('[data-class-choice="mage"]');
  let initial = await evalJs(`({kit:document.getElementById('kitCount').textContent, party:document.getElementById('partyRoster').innerText})`);
  await click('[data-menu="skills"]'); await click('[data-action="venom"]');
  await click('[data-action="attack"]'); await click('[data-action="attack"]');
  await wait(850);
  let status = await evalJs(`({log:document.getElementById('logText').textContent,intent:document.getElementById('intentText').textContent,enemy:document.getElementById('enemyHpText').textContent,legacy:JSON.parse(localStorage.getItem('emberfall-legacy'))})`);
  // Reset during the active run to verify earned shards are banked once, then reload to verify persistence.
  await evalJs(`window.confirm=()=>true`); await click('#resetBtn');
  let banked = await evalJs(`JSON.parse(localStorage.getItem('emberfall-legacy'))`);
  await click('#resetBtn');
  let secondBank = await evalJs(`JSON.parse(localStorage.getItem('emberfall-legacy'))`);
  await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
  let mobile = await evalJs(`({width:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth,viewport:innerWidth})`);
  const shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
  fs.writeFileSync('/tmp/opencode/emberfall-mobile.png',Buffer.from(shot.result.data,'base64'));
  await send('Emulation.setDeviceMetricsOverride',{width:1440,height:1000,deviceScaleFactor:1,mobile:false});
  let desktop = await evalJs(`({width:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth})`);
  console.log(JSON.stringify({initial,status,banked,secondBank,mobile,desktop},null,2));
  ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

