381:           showFloat(`+${healed}`, 'heal', actorIndex === 0); log(`${actor.name} drinks a health potion and recovers ${healed} vitality.`); beep(520); turnConsumed = true; break;
382:         }
383:         case 'ether': {
384:           if (!state.ethers || state.mp >= state.maxMp) return;
385:           state.ethers--;
