const http=require('http');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function getJson(path){return new Promise((resolve,reject)=>http.get(`http://127.0.0.1:9222${path}`,res=>{let s='';res.on('data',x=>s+=x);res.on('end',()=>resolve(JSON.parse(s)));}).on('error',reject));}
(async()=>{
 const target=(await getJson('/json/list')).find(x=>x.type==='page'&&x.url.startsWith('http://127.0.0.1:8765'));
 const ws=new WebSocket(target.webSocketDebuggerUrl); await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
 let seq=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}};
 const send=(method,params={})=>new Promise(resolve=>{const id=++seq;pending.set(id,resolve);ws.send(JSON.stringify({id,method,params}));});
 const ev=async expression=>{const x=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(x.result.exceptionDetails)throw Error(x.result.exceptionDetails.text);return x.result.result.value;};
 const click=sel=>ev(`(()=>{const e=document.querySelector(${JSON.stringify(sel)});if(!e)throw Error('missing '+${JSON.stringify(sel)});e.click();return true})()`);
 const wait=ms=>sleep(ms);
 await send('Page.enable');await send('Runtime.enable');
 await ev(`localStorage.setItem('emberfall-legacy',JSON.stringify({shards:0,achievements:[],boons:[]}));location.reload()`);await wait(400);
 await click('[data-class-choice="knight"]');
 for(let i=0;i<8;i++){if(await ev(`!document.getElementById('shopModal').classList.contains('hidden')`))break;await click('[data-action="attack"]');await wait(800);}
 const shop=await ev(`({visible:!document.getElementById('shopModal').classList.contains('hidden'),floor:document.getElementById('floorTop').textContent,log:document.getElementById('logText').textContent})`);
 await ev('window.confirm=()=>true');await click('#resetBtn');const first=await ev(`JSON.parse(localStorage.getItem('emberfall-legacy'))`);await click('#resetBtn');const second=await ev(`JSON.parse(localStorage.getItem('emberfall-legacy'))`);
 await ev(`localStorage.setItem('emberfall-legacy',JSON.stringify({shards:10,achievements:['elements'],boons:[]}));location.reload()`);await wait(400);
 const before=await ev(`JSON.parse(localStorage.getItem('emberfall-legacy'))`);await click('[data-boon="vitality"]');const bought=await ev(`({legacy:JSON.parse(localStorage.getItem('emberfall-legacy')),owned:document.querySelector('[data-boon="vitality"]').disabled})`);await ev('location.reload()');await wait(400);
 const persisted=await ev(`({legacy:JSON.parse(localStorage.getItem('emberfall-legacy')),achievements:document.querySelectorAll('.achievement.earned').length,owned:document.querySelector('[data-boon="vitality"]').classList.contains('owned')})`);
 console.log(JSON.stringify({shop,first,second,before,bought,persisted},null,2));ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

