const http=require('http');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function getJson(path){return new Promise((resolve,reject)=>http.get(`http://127.0.0.1:9222${path}`,res=>{let s='';res.on('data',x=>s+=x);res.on('end',()=>resolve(JSON.parse(s)));}).on('error',reject));}
(async()=>{
 const target=(await getJson('/json/list')).find(x=>x.type==='page'&&x.url.startsWith('http://127.0.0.1:8765'));
 const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});let seq=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}};
 const send=(method,params={})=>new Promise(resolve=>{const id=++seq;pending.set(id,resolve);ws.send(JSON.stringify({id,method,params}));});
 const ev=async expression=>{const x=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(x.result.exceptionDetails)throw Error(x.result.exceptionDetails.text);return x.result.result.value;};
 const click=sel=>ev(`(()=>{const e=document.querySelector(${JSON.stringify(sel)});if(!e)throw Error('missing '+${JSON.stringify(sel)});if(!e.disabled)e.click();return true})()`);const wait=ms=>sleep(ms);
 await send('Page.enable');await send('Runtime.enable');
 await ev(`localStorage.setItem('emberfall-legacy',JSON.stringify({shards:0,achievements:[],boons:['phoenix']}));location.reload()`);await wait(400);
 await ev(`(()=>{const original=Math.random;Math.random=function(){const stack=new Error().stack||'';if(stack.includes('enemyTurn'))return .99;if(stack.includes('doAction'))return 0;return original()};return true})()`);
 await click('[data-class-choice="knight"]');let revived=false;let maxRounds=0;
 for(let floor=1;floor<=15&&!revived;floor++){
  if(await ev(`!document.getElementById('shopModal').classList.contains('hidden')`)){await click('#continueBtn');await wait(80);}
  for(let round=0;round<20&&!revived;round++){
   if(await ev(`!document.getElementById('gameOverModal').classList.contains('hidden')`))throw Error('game over before revive');
   if(await ev(`!document.getElementById('shopModal').classList.contains('hidden')`))break;
   for(let act=0;act<3;act++){
    const status=await ev(`({shop:!document.getElementById('shopModal').classList.contains('hidden'),over:!document.getElementById('gameOverModal').classList.contains('hidden')})`);if(status.shop||status.over)break;
    await click('[data-action="attack"]');await wait(35);
   }
   await wait(760);maxRounds++;
   const check=await ev(`({down:document.querySelectorAll('.party-member.down').length,kit:document.getElementById('kitCount').textContent,log:document.getElementById('logText').textContent})`);
   if(check.down){
    const pre=await ev(`({party:document.getElementById('partyList').innerText,kit:document.getElementById('kitCount').textContent,phoenix:!!document.querySelector('[data-action="phoenix"]'),enabled:!document.querySelector('[data-action="phoenix"]').disabled})`);
    if(!pre.enabled) throw Error('Phoenix action disabled despite fallen party member: '+JSON.stringify(pre));
    await click('[data-action="phoenix"]');await wait(80);
    const post=await ev(`({party:document.getElementById('partyList').innerText,kit:document.getElementById('kitCount').textContent,log:document.getElementById('logText').textContent,achievement:JSON.parse(localStorage.getItem('emberfall-legacy')).achievements.includes('phoenix')})`);
    console.log(JSON.stringify({floor,pre,post,rounds:maxRounds},null,2));revived=true;break;
   }
  }
 }
 if(!revived)throw Error('No fallen member before test limit');ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

